package com.example.adventureref;

import net.kyori.adventure.key.Key;
import net.kyori.adventure.sound.Sound;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import net.kyori.adventure.text.minimessage.MiniMessage;
import net.kyori.adventure.title.Title;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.plugin.java.JavaPlugin;

import java.time.Duration;
import java.util.List;
import java.util.Objects;

/**
 * Reference: Adventure API for Paper 1.21.
 *
 * KEY RULES:
 *  - NEVER use org.bukkit.ChatColor — it is removed in 1.21.
 *  - NEVER call player.sendMessage(String) — use Component overloads.
 *  - Use MiniMessage for any user-configurable/config-driven message strings.
 *  - Suppress italic decoration (.decoration(TextDecoration.ITALIC, false)) on item display names and lore.
 *  - ItemMeta.displayName() and ItemMeta.lore() take Component / List<Component>, NOT String.
 *
 * KEY NAMESPACE RULES (Adventure 5.1.0+, strictly enforced):
 *  - Key namespaces MUST be lowercase [a-z0-9_.-] only — NEVER uppercase, never spaces.
 *  - CORRECT: Key.key("myplugin", "item_name") or Key.key("myplugin:item_name")
 *  - WRONG:   Key.key("MyPlugin", "ItemName")  <-- throws IllegalArgumentException at runtime
 *  - WRONG:   Key.key("..", "value")            <-- '..' namespace is explicitly disallowed
 *
 * CLICK EVENT RULES (Adventure 5.1.0+, validated at construction time):
 *  - ClickEvent.openUrl() payload must be a full URL with scheme: "https://..." or "http://..."
 *  - ClickEvent.changePage() page number must be >= 1 (page 0 throws)
 *  - ClickEvent.runCommand() and suggestCommand() payload should start with '/'
 */
public class AdventureRef extends JavaPlugin implements CommandExecutor {

    // MiniMessage singleton — reuse this, never create a new one per request.
    private static final MiniMessage MM = MiniMessage.miniMessage();

    @Override
    public void onEnable() {
        Objects.requireNonNull(getCommand("adventure-demo")).setExecutor(this);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {
        if (!(sender instanceof Player player)) {
            // For non-player senders, Component still works.
            sender.sendMessage(Component.text("Players only.", NamedTextColor.RED));
            return true;
        }

        // --- Basic composite Component ---
        player.sendMessage(
                Component.text("Hello ", NamedTextColor.GOLD)
                        .append(Component.text(player.getName(), NamedTextColor.YELLOW, TextDecoration.BOLD))
                        .append(Component.text("!", NamedTextColor.GOLD)));

        // --- MiniMessage: preferred for config-driven or gradient text ---
        Component parsed = MM.deserialize(
                "<gradient:green:aqua><bold>StackNest</bold></gradient> <gray>v1.0</gray>");
        player.sendMessage(parsed);

        // --- Title (main + subtitle + fade timing) ---
        player.showTitle(Title.title(
                Component.text("Round Start", NamedTextColor.GOLD, TextDecoration.BOLD),
                Component.text("Good luck!", NamedTextColor.GRAY),
                Title.Times.times(
                        Duration.ofMillis(500),
                        Duration.ofSeconds(3),
                        Duration.ofMillis(500))));

        // --- ActionBar ---
        player.sendActionBar(Component.text("ActionBar message", NamedTextColor.AQUA));

        // --- Sound via Adventure ---
        player.playSound(
                Sound.sound(Key.key("entity.player.levelup"), Sound.Source.MASTER, 1f, 1f));

        // --- ItemStack with Adventure display name + lore ---
        ItemStack item = new ItemStack(Material.DIAMOND_SWORD);
        ItemMeta meta = item.getItemMeta();
        meta.displayName(
                // .decoration(ITALIC, false) prevents the default italic in item names
                Component.text("Legendary Blade", NamedTextColor.BLUE, TextDecoration.BOLD)
                        .decoration(TextDecoration.ITALIC, false));
        meta.lore(List.of(
                Component.text("Deals 10 damage", NamedTextColor.GRAY)
                        .decoration(TextDecoration.ITALIC, false),
                MM.deserialize("<red>Cursed</red>").decoration(TextDecoration.ITALIC, false)));
        item.setItemMeta(meta);
        player.getInventory().addItem(item);

        return true;
    }
}
